 static final String P="local/lito381/server/",N=P+"NativeSourceCubePlayer",PC=P+"ClientSession",CTX=P+"NativeAreaMaterialAction$Context",PLAN=P+"NativeSourceDamageDisplay$Plan",RAW=P+"NativeSourceRawDamage",COM=P+"NativePlayerCommit",DISPLAY=P+"NativeSourceDamageDisplay",ATT=P+"NativeCombatAttacker",REF=ATT+"$Ref";
