  if(c.name.equals(RAW)){int count=0;for(var m:c.methods)if(m.name.equals("beforeEvent")){reject(m,"beforeEvent","(L"+PC+";L"+COM+"$Event;)Z",false);count++;}if(count!=1)throw new AssertionError("existing actual HP precommit gate");return;}
  if(c.name.equals(COM)){int count=0;for(var m:c.methods)if(m.name.equals("validFrame")){reject(m,"validFrame","(L"+PC+";)Z",true);count++;}if(count!=1)throw new AssertionError("original accepted Frame gate");return;}
  if(c.name.equals(DISPLAY)){int count=0;for(var m:c.methods)if(m.name.equals("acceptedState")){var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new MethodInsnNode(INVOKESTATIC,N,"accepted","(L"+COM+"$Frame;)V",false));m.instructions.insert(x);count++;}if(count!=1)throw new AssertionError("actual accepted death-token boundary");return;}
  int count=0;for(var m:c.methods)if(Set.of("alive","feedback","acceptedFeedback","reaction").contains(m.name)){var legacy=new LabelNode();var x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(new MethodInsnNode(INVOKESTATIC,N,"effect","(L"+REF+";)Z",false));x.add(new JumpInsnNode(IFEQ,legacy));
   if(m.name.equals("alive")){x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,1));x.add(new MethodInsnNode(INVOKESTATIC,N,"alive","(L"+PC+";L"+REF+";)Z",false));x.add(new InsnNode(IRETURN));}
   else if(m.name.equals("feedback")){x.add(new InsnNode(ACONST_NULL));x.add(new InsnNode(ARETURN));}else x.add(new InsnNode(RETURN));x.add(legacy);m.instructions.insert(x);count++;
  }if(count!=4)throw new AssertionError("kind5 effect liveness and no reactive feedback only");
